  K.buoy = (color) => { const g = new THREE.Group(); const b = new THREE.Mesh(new THREE.CylinderGeometry(.5, .7, 1.2, 8), matte(0x94a3b8)); b.position.y = .6; g.add(b); const s = sprite(color || P.green, 2.4, .9); s.position.y = 2; g.add(s); g.userData.light = s.material; return g; };
