  /* ---------- village layout (shared by village card, rural hero and rural pipeline) ---------- */
  function villageLayout(T, r) {
    const roadZ = (x) => Math.sin(x * .09) * 5;
    const main = []; for (let i = 0; i <= 44; i++) { const x = -48 + i * 2.2; main.push(V3(x, T.userData.h(x, roadZ(x)) + .12, roadZ(x))); }
    const side = []; for (let i = 0; i <= 16; i++) { const z = roadZ(2) + i * 2.2, x = 2 + Math.sin(i * .4) * 1.4; side.push(V3(x, T.userData.h(x, z) + .12, z)); }
    const houses = [];
    for (let i = 0; i < 11; i++) { const x = -36 + i * 7.2; [-1, 1].forEach((sd) => { if (r() < .2) return; if (sd > 0 && Math.abs(x - 2) < 5) return; const z = roadZ(x) + sd * (5.6 + r() * 2.4); houses.push({ x: x + (r() - .5) * 1.6, z, rot: sd > 0 ? 1 : 0, w: 3.2 + r() * 1.6, d: 2.6 + r() * 1.2, h: 1.5 + r() * .5 }); }); }
    for (let i = 1; i < 5; i++) { const z = roadZ(2) + i * 7.4; [-1, 1].forEach((sx) => { if (r() < .25) return; houses.push({ x: 2 + sx * (5.2 + r() * 2), z: z + (r() - .5) * 1.4, rot: sx > 0 ? -.5 : .5, w: 3 + r() * 1.4, d: 2.6 + r(), h: 1.5 + r() * .4 }); }); }
    const school = { x: -18, z: roadZ(-18) + 13, w: 8, d: 4, h: 2.8 };
    const clinic = { x: 20, z: roadZ(20) - 12, w: 5.5, d: 3.6, h: 2.4 };
    const power = { x: 36, z: -22 };
    const beam = { x: -32, z: roadZ(-32) + 15 };
    const trees = []; let tries = 0;
    while (trees.length < 30 && tries++ < 600) { const x = -50 + r() * 100, z = -34 + r() * 70; if (Math.abs(z - roadZ(x)) < 4.2 && x < 50) continue; if (Math.abs(x - 2) < 4.2 && z > roadZ(2) - 2 && z < roadZ(2) + 38) continue; if (houses.some((h) => Math.hypot(h.x - x, h.z - z) < 5)) continue; if (Math.hypot(school.x - x, school.z - z) < 7 || Math.hypot(clinic.x - x, clinic.z - z) < 6) continue; if (Math.hypot(power.x - x, power.z - z) < 14 || Math.hypot(beam.x - x, beam.z - z) < 4) continue; if (trees.some((t) => Math.hypot(t.x - x, t.z - z) < 3.4)) continue; trees.push({ x, z, s: 1 + r() * .9, k: r() }); }
    const poles = []; for (let i = 8; i >= 0; i--) { const x = -44 + i * 11; poles.push(V3(x, T.userData.h(x, roadZ(x) - 3.1), roadZ(x) - 3.1)); }
    const poles2 = []; for (let i = 0; i < 4; i++) { const z = roadZ(2) + 1 + i * 11; poles2.push(V3(-1.4, T.userData.h(-1.4, z), z)); }
    return { main, side, houses, school, clinic, power, beam, trees, poles, poles2, roadZ };
  }
  function buildVillage(T, r, into, F) {
    const V = villageLayout(T, r), civil = into.civil || into, grid = into.grid || into;
    civil.add(K.road(V.main, 2.6), K.road(V.side, 2));
    const hs = [];
    V.houses.forEach((h) => { const m = named(K.house(h.w, h.d, h.h, h.rot), 'HOUSEHOLD · ' + (2 + (r() * 3) | 0) + '.' + ((r() * 9) | 0) + ' kWh/day'); m.position.set(h.x, T.userData.h(h.x, h.z), h.z); civil.add(m); hs.push(m); F.push(m); });
    const school = named(K.building(V.school.w, V.school.h, V.school.d, P.cyan, 5, 1), 'SCHOOL · 6.4 kWh/day'); school.position.set(V.school.x, T.userData.h(V.school.x, V.school.z), V.school.z); civil.add(school); F.push(school);
    const clinic = named(K.building(V.clinic.w, V.clinic.h, V.clinic.d, P.green, 3, 1), 'HEALTH POST · 9.8 kWh/day · COLD CHAIN'); clinic.position.set(V.clinic.x, T.userData.h(V.clinic.x, V.clinic.z), V.clinic.z); clinic.rotation.y = Math.PI; civil.add(clinic); F.push(clinic);
    V.trees.forEach((t) => { const tr = K.tree(t.s, t.k); tr.position.set(t.x, T.userData.h(t.x, t.z), t.z); civil.add(tr); });
    // powerhouse: array + battery + control room, fenced
    const px = V.power.x, pz = V.power.z, py = T.userData.h(px, pz);
    const pv = named(K.pv(4, 5, 2.2, 1.7, P.blue), 'PV ARRAY · 39 kWp'); pv.position.set(px - 2, py, pz - 1); grid.add(pv); F.push(pv);
    const bess = named(K.bess(), 'BATTERY · 163 kWh'); bess.position.set(px + 6, py, pz + 5); grid.add(bess); F.push(bess);
    const ctl = named(K.building(3.2, 2.2, 2.4, P.cyan, 2, 1), 'POWERHOUSE · 30 kVA'); ctl.position.set(px + 1, py, pz + 6); grid.add(ctl); F.push(ctl);
    grid.add(K.fence([[px - 9, py, pz - 6], [px + 10, py, pz - 6], [px + 10, py, pz + 9], [px - 9, py, pz + 9], [px - 9, py, pz - 6]], P.blue2));
    grid.add(K.tube([V3(px - 2, py + 1.4, pz - 1), V3(px + 3, py + 1.6, pz + 3), V3(px + 6, py + 1.4, pz + 5)], P.blue2, .09, .8, 2));
    grid.add(K.tube([V3(px + 6, py + 1.4, pz + 5), V3(px + 3.5, py + 1.5, pz + 6), V3(px + 1, py + 1.2, pz + 6)], P.cyan, .09, .7, 2));
    // distribution: feeder to the first pole, then along the road, then up the side road
    const line = K.poleLine(V.poles, P.cyan2, { h: 5.4 }); grid.add(line);
    const p0 = line.userData.tops[0][1];
    grid.add(K.tube([V3(px + 1, py + 1.6, pz + 6), V3((px + 1 + p0.x) / 2, py + 4, (pz + 6 + p0.z) / 2), p0], P.cyan, .07, .7, 2));
    const line2 = K.poleLine(V.poles2, P.cyan2, { h: 5 }); grid.add(line2);
    const j0 = K.nearestTop(line.userData.tops, V.poles2[0].x, V.poles2[0].z); grid.add(K.tube([j0, V3((j0.x + line2.userData.tops[0][0].x) / 2, j0.y - .6, (j0.z + line2.userData.tops[0][0].z) / 2), line2.userData.tops[0][0]], P.cyan2, .045, .5, 1, .9));
    const tops = line.userData.tops.concat(line2.userData.tops);
    [...hs, school, clinic].forEach((h) => { const t = K.nearestTop(tops, h.position.x, h.position.z); if (t) grid.add(K.drop(t, V3(h.position.x, h.position.y + 2.1, h.position.z))); });
    return { V, hs, pv, bess, line, line2 };
  }

